'use client'
import { useEffect, useLayoutEffect, useState } from 'react'
import { BAR, MenuSheet } from '@/react/components/site/MenuSheet'
import { GLYPH } from '@/react/components/site/MenuPanels'
import { NAV_LINK, NavMenus } from '@/react/components/site/NavMenus'
import { NavIcon } from '@/react/components/site/NavIcon'
import { SHEET_LINK, SheetDisclosure } from '@/react/components/site/SheetDisclosure'
import { Button } from '@/react/components/ui/Button'
import { Logo } from '@/react/components/visuals/Logo'
import { headerLabels, headerMenus, headerNav, type HeaderLabels, type HeaderMenus, type NavEntry } from '@/lib/site-header'
import { cn } from '@/react/lib/cn'
import { homeLinkClick } from '@/lib/home-link'

// The site's header (site/Header: Header, HomeLink, ScrollGround, HeaderKey, NavMenus, MenuSheet): 64px, 72px from
// 1024, in the page's container; the lockup (20px) on the left, from 1280 the links and their menus centered (NavMenus)
// and on the right the sign-in in the links' style beside the White 36px key ("Get API key" under 424px, gone under
// 372). Below 1280 the links fold into the phone sheet (MenuSheet): its menus as disclosures of their rows, its other
// links, the sign-in and the key at its foot. Once the page scrolls 8px the bar takes a Black ground and a hairline
// (fading in, 160ms). With `hideKeyUntil` (a selector, a hero's actions) the key waits, hidden, until that element
// passes under the bar, then grows in and the sign-in slides aside for it. `variant`: default; centered (links and
// menus from 1024); minimal (the lockup and the key only). Menu content comes through `menus` (Acme by default).
export interface HeaderLink extends NavEntry {}

export interface HeaderAction {
  label: string
  href: string
  /** A shorter label for the narrowest phones (the key). */
  short?: string
}

export interface SiteHeaderProps {
  /** The links; entries with `menu` (products, useCases, resources) open that menu. */
  links?: HeaderLink[]
  /** The menus' content. */
  menus?: HeaderMenus
  /** The White key on the right. */
  cta?: HeaderAction
  /** The sign-in before it. */
  secondary?: HeaderAction
  /** Where the lockup links. */
  homeHref?: string
  /** The lockup's accessible name. */
  label?: string
  /** default (links and menus from 1280), centered (from 1024) or minimal (the lockup and the key only). */
  variant?: 'default' | 'centered' | 'minimal'
  /** Keep the key hidden until the element this selector finds has passed under the bar. */
  hideKeyUntil?: string
  /** Stay at the top while the page scrolls (sticky), or scroll away with it. */
  sticky?: boolean
  labels?: HeaderLabels
  className?: string
}

const GRID = { default: 'xl:grid xl:grid-cols-[1fr_auto_1fr]', centered: 'lg:grid lg:grid-cols-[1fr_auto_1fr]', minimal: '' }
const SIGN_IN = { default: 'hidden xl:flex', centered: 'hidden lg:flex', minimal: 'hidden' }
const FROM = { default: 1280, centered: 1024, minimal: 1280 }

function useScrolled() {
  const [scrolled, setScrolled] = useState(false)
  useEffect(() => {
    const on = () => setScrolled(window.scrollY > 8)
    on()
    window.addEventListener('scroll', on, { passive: true })
    return () => window.removeEventListener('scroll', on)
  }, [])
  return scrolled
}

function useKeyShown(selector?: string) {
  const [shown, setShown] = useState<'shown' | 'hidden'>('shown')
  const [instant, setInstant] = useState(true)
  useLayoutEffect(() => {
    const hero = selector ? document.querySelector(selector) : null
    const bar = () => parseFloat(getComputedStyle(document.documentElement).getPropertyValue(window.matchMedia('(min-width: 1024px)').matches ? '--ds-size-header' : '--ds-header-bar-phone')) || 0
    const state = (rect: DOMRectReadOnly | null, top: number) => (!rect || (!rect.width && !rect.height) || rect.top < top ? 'shown' : 'hidden')
    setShown(state(hero?.getBoundingClientRect() ?? null, bar()))
    setInstant(true)
    let frame = requestAnimationFrame(() => setInstant(false))
    if (!hero) return () => cancelAnimationFrame(frame)
    let observer: IntersectionObserver | null = null
    let top = -1
    const watch = () => {
      const next = bar()
      if (next === top) return
      top = next
      observer?.disconnect()
      observer = new IntersectionObserver(([entry]) => {
        if (!entry) return
        setShown(state(entry.boundingClientRect, top))
        if (!frame) frame = requestAnimationFrame(() => setInstant(false))
      }, { rootMargin: `-${top}px 0px 0px 0px`, threshold: [0, 1] })
      observer.observe(hero)
    }
    watch()
    window.addEventListener('resize', watch)
    return () => {
      window.removeEventListener('resize', watch)
      observer?.disconnect()
      cancelAnimationFrame(frame)
    }
  }, [selector])
  return { shown, instant }
}

export function SiteHeader({
  links = headerNav,
  menus = headerMenus,
  cta = { label: 'Get a free API key', href: '#start', short: 'Get API key' },
  secondary = { label: 'Sign in', href: '#sign-in' },
  homeHref = '/',
  label = 'Spyglass',
  variant = 'default',
  hideKeyUntil,
  sticky = true,
  labels = headerLabels,
  className,
}: SiteHeaderProps) {
  const scrolled = useScrolled()
  const { shown, instant } = useKeyShown(hideKeyUntil)
  const hidden = shown === 'hidden'
  const brand = (
    <a href={homeHref} aria-label={label} data-home-link="" onClick={(e) => homeLinkClick(e.nativeEvent)} className="-ms-2 block flex-none rounded-ds-sm px-2 py-3 text-fg md:-ms-3 md:px-3 md:py-2 lg:py-3 xl:justify-self-start">
      <Logo height={20} label={label} />
    </a>
  )
  const key = () => cta ? (
    <Button href={cta.href} size="xs" className="ds-key">
      <span className="ds-key-full truncate">{cta.label}</span>
      <span className="ds-key-short truncate">{cta.short ?? cta.label}</span>
    </Button>
  ) : null
  const sheetRows = (entry: NavEntry) => {
    if (entry.menu === 'products') { const m = menus.products ?? headerMenus.products; return [...m.offers, ...(m.soon ? [m.soon] : [])].map((r) => ({ key: r.key, name: r.name, href: r.href, icon: r.icon })) }
    if (entry.menu === 'useCases') return (menus.useCases ?? headerMenus.useCases).rows.map((r) => ({ key: r.key, name: r.name, href: r.href, icon: r.icon }))
    return []
  }

  return (
    <header data-ds="site-header" data-variant={variant} className={cn('ds-site-header z-20 text-fg', sticky ? 'sticky top-0' : 'relative', className)}>
      <style href="ds-site-header" precedence="ds">{css}</style>
      <span aria-hidden="true" data-on={scrolled || undefined} className="pointer-events-none absolute inset-0 border-b border-edge bg-surface opacity-0 transition-opacity duration-160 ease-out data-on:opacity-100" />
      <div className={cn(BAR, GRID[variant])}>
        {brand}
        {variant !== 'minimal' ? <NavMenus links={links} menus={menus} label={labels.nav} from={FROM[variant]} /> : null}
        <div className="ds-actions flex min-w-0 flex-[0_1_auto] items-center gap-1 md:gap-2 xl:min-w-auto xl:justify-self-end xl:gap-3">
          <div data-key={shown} data-instant={instant || undefined} className="ds-key-slot relative flex min-w-0 flex-[0_1_auto]">
            <div className="ds-key-room pointer-events-none absolute inset-0">
              {secondary ? <a href={secondary.href} className={cn(NAV_LINK, SIGN_IN[variant], 'pointer-events-auto absolute inset-y-0 right-[calc(100%+var(--ds-space-md))] my-auto px-3 whitespace-nowrap')}>{secondary.label}</a> : null}
            </div>
            <div inert={hidden} aria-hidden={hidden || undefined} className="ds-key-box flex min-w-0">{key()}</div>
          </div>
          {variant !== 'minimal' ? (
            <MenuSheet
              label={labels.menu}
              closeLabel={labels.close}
              until={FROM[variant]}
              brand={brand}
              action={<div className="flex min-w-0 flex-[0_1_auto]">{key()}</div>}
              foot={
                <>
                  {secondary ? <Button href={secondary.href} variant="secondary" className="w-full">{secondary.label}</Button> : null}
                  {cta ? <div className="contents md:hidden"><Button href={cta.href} className="w-full">{cta.label}</Button></div> : null}
                </>
              }
            >
              <nav aria-label={labels.nav} className="mx-auto w-full max-w-[calc(var(--ds-layout-content)+2*var(--ds-layout-gutter))] px-(--ds-layout-gutter)">
                <ul>
                  {links.map((entry) => (
                    <li key={entry.label} className="flex flex-col border-t border-edge first:border-t-0 last:border-b">
                      {entry.menu && entry.menu !== 'resources' ? (
                        <SheetDisclosure label={entry.label}>
                          <ul className="grid gap-x-4 pb-2 md:grid-cols-2">
                            {sheetRows(entry).map((row) => (
                              <li key={row.key}>
                                <a href={row.href} className="-mx-2 flex min-h-12 items-center gap-3 rounded-control px-2 type-body text-fg transition-[color] duration-160 ease-out outline-offset-[calc(-1*var(--ds-space-xs))] hover:text-fg-soft active:text-fg-soft">
                                  <span className={cn(GLYPH, 'size-8 rounded-ds-sm')}><NavIcon name={row.icon} /></span>
                                  {row.name}
                                </a>
                              </li>
                            ))}
                          </ul>
                        </SheetDisclosure>
                      ) : (
                        <a href={entry.menu === 'resources' ? (menus.resources ?? headerMenus.resources).all.href : entry.href} aria-current={entry.current ? 'page' : undefined} className={SHEET_LINK}>{entry.label}</a>
                      )}
                    </li>
                  ))}
                </ul>
              </nav>
            </MenuSheet>
          ) : null}
        </div>
      </div>
    </header>
  )
}

export default SiteHeader

const css = `
.ds-key-box { transition: opacity var(--ds-duration-entrance) var(--ds-easing-out) var(--ds-duration-slow), transform var(--ds-duration-entrance) var(--ds-easing-out) var(--ds-duration-slow), visibility var(--ds-duration-instant) linear; }
.ds-key-room { transition: transform var(--ds-duration-slow) var(--ds-easing-out); }
.ds-key-slot[data-key="hidden"] .ds-key-box {
  opacity: 0; transform: scale(var(--ds-menu-from-scale)); visibility: hidden; pointer-events: none;
  transition: opacity var(--ds-duration-close) var(--ds-easing-out), transform var(--ds-duration-close) var(--ds-easing-out), visibility var(--ds-duration-instant) linear var(--ds-duration-close);
}
.ds-key-slot[data-instant] .ds-key-box, .ds-key-slot[data-instant] .ds-key-room { transition: none; }
.ds-key-short { display: none; }
@media (max-width: 423px) {
  .ds-actions { gap: 0; }
  .ds-key-full { display: none; }
  .ds-key-short { display: block; }
}
@media (max-width: 371px) { .ds-key-slot .ds-key { display: none; } }
@media (min-width: 1024px) {
  .ds-site-header[data-variant="centered"] .ds-key-slot[data-key="hidden"] .ds-key-room { transform: translateX(calc(100% + var(--ds-space-xl))); transition-delay: var(--ds-duration-close); }
}
@media (min-width: 1280px) {
  .ds-site-header[data-variant="default"] .ds-key-slot[data-key="hidden"] .ds-key-room { transform: translateX(calc(100% + var(--ds-space-xl))); transition-delay: var(--ds-duration-close); }
}
@media (prefers-reduced-motion: reduce) {
  .ds-key-box { transition: opacity var(--ds-duration-micro) var(--ds-easing-out), visibility var(--ds-duration-instant) linear; }
  .ds-key-slot[data-key="hidden"] .ds-key-box { transform: none; transition: opacity var(--ds-duration-micro) var(--ds-easing-out), visibility var(--ds-duration-instant) linear var(--ds-duration-micro); }
  .ds-key-room { transition: none; }
}
`

'use client'
import { useEffect, useId, useRef, useState, type FocusEvent, type KeyboardEvent, type MouseEvent, type PointerEvent, type ReactNode } from 'react'
import { ResourcesPanel, UseCasesPanel } from '@/react/components/site/MenuPanels'
import { Chevron } from '@/react/components/site/NavIcon'
import { ProductsLivePanel } from '@/react/components/site/ProductsLivePanel'
import { headerMenus, headerNav, MENU_GRACE_MS, MENU_INTENT_MS, type HeaderMenus, type MenuKey, type NavEntry } from '@/lib/site-header'
import { cn } from '@/react/lib/cn'

// The site header's links and menus (site/Header NavMenus): DM Sans 14/20 links in the soft gray, 36px tall with 16px
// in, filling #262626 under the pointer; Products, Use cases and Resources open their panels 24px under the bar.
// Under a mouse a menu opens after a short pause (80ms) and, once one is open, moving to another swaps at once; leaving
// the links and the panel closes it after 240ms. A click opens it and keeps it open (a second click closes it); Enter,
// Space or ArrowDown open it with focus on its first link (ArrowUp on its last), arrows, Home and End move through its
// links, Escape closes it and gives focus back to its link, and a click or focus outside closes it. A panel opens by
// fading in, rising 8px and growing from 96% (240ms; 160ms out); from the keyboard, or swapping, it appears at once.
// Reduced motion keeps the fade.
export const NAV_LINK = 'relative flex h-control-xs items-center rounded-control px-4 type-ui text-fg-soft transition-[color,background-color] duration-160 ease-out after:absolute after:inset-x-0 after:-inset-y-1 hover:bg-surface-raised hover:text-fg focus-visible:text-fg active:text-fg aria-[current=page]:text-fg'

type Via = 'hover' | 'click'

const WIDTH: Record<MenuKey, string> = {
  products: 'w-[min(var(--ds-header-menu-products-w),calc(100vw-2*var(--ds-layout-gutter)))]',
  useCases: 'w-[min(var(--ds-header-menu-cases-w),calc(100vw-2*var(--ds-layout-gutter)))]',
  resources: 'w-[min(var(--ds-header-menu-resources-w),calc(100vw-2*var(--ds-layout-gutter)))]',
}

function links(panel: HTMLElement | null | undefined) {
  return panel ? [...panel.querySelectorAll<HTMLElement>('a[href]:not([tabindex="-1"])')].filter((a) => a.getClientRects().length > 0) : []
}

export interface NavMenusProps {
  /** The links; entries with `menu` open that menu. */
  links?: NavEntry[]
  menus?: HeaderMenus
  /** The nav's accessible name. */
  label?: string
  /** The width the links show from (1280 or 1024); hidden below it. */
  from?: number
  className?: string
}

export function NavMenus({ links: entries = headerNav, menus = headerMenus, label = 'Main', from = 1280, className }: NavMenusProps) {
  const [open, setOpen] = useState<MenuKey | null>(null)
  const [instant, setInstant] = useState(false)
  const navRef = useRef<HTMLElement>(null)
  const triggers = useRef<Partial<Record<MenuKey, HTMLButtonElement | null>>>({})
  const panels = useRef<Partial<Record<MenuKey, HTMLDivElement | null>>>({})
  const via = useRef<Via>('click')
  const timer = useRef<number | undefined>(undefined)
  const pendingFocus = useRef<'first' | 'last' | null>(null)
  const openRef = useRef<MenuKey | null>(null)
  const uid = useId()
  const panelId = (key: MenuKey) => `${uid}-${key}`

  const clearTimer = () => {
    window.clearTimeout(timer.current)
    timer.current = undefined
  }
  const show = (key: MenuKey, how: Via, keyboard = false) => {
    clearTimer()
    via.current = how
    setInstant(keyboard || (openRef.current !== null && openRef.current !== key))
    openRef.current = key
    setOpen(key)
  }
  const hide = () => {
    clearTimer()
    openRef.current = null
    setInstant(false)
    setOpen(null)
  }

  useEffect(() => {
    if (!open || !pendingFocus.current) return
    const items = links(panels.current[open])
    const target = pendingFocus.current === 'first' ? items[0] : items[items.length - 1]
    pendingFocus.current = null
    target?.focus()
  }, [open])

  useEffect(() => {
    if (!open) return
    const nav = navRef.current
    const onKeyDown = (e: globalThis.KeyboardEvent) => {
      if (e.key !== 'Escape') return
      const hadFocus = nav?.contains(document.activeElement)
      hide()
      if (hadFocus) triggers.current[open]?.focus()
    }
    const onPointerDown = (e: globalThis.PointerEvent) => { if (nav && !nav.contains(e.target as Node)) hide() }
    const wide = window.matchMedia(`(min-width: ${from}px)`)
    const onNarrow = () => { if (!wide.matches) hide() }
    document.addEventListener('keydown', onKeyDown)
    document.addEventListener('pointerdown', onPointerDown)
    wide.addEventListener('change', onNarrow)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      document.removeEventListener('pointerdown', onPointerDown)
      wide.removeEventListener('change', onNarrow)
    }
  }, [open, from])

  useEffect(() => () => window.clearTimeout(timer.current), [])

  const onTriggerClick = (key: MenuKey, e: MouseEvent<HTMLButtonElement>) => {
    clearTimer()
    const keyboard = e.detail === 0
    if (open === key) {
      if (via.current === 'hover' && !keyboard) {
        via.current = 'click'
        return
      }
      hide()
      return
    }
    if (keyboard) pendingFocus.current = 'first'
    show(key, 'click', keyboard)
  }
  const onTriggerKeyDown = (key: MenuKey, e: KeyboardEvent<HTMLButtonElement>) => {
    if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return
    e.preventDefault()
    if (open === key) {
      const items = links(panels.current[key])
      ;(e.key === 'ArrowDown' ? items[0] : items[items.length - 1])?.focus()
      return
    }
    pendingFocus.current = e.key === 'ArrowDown' ? 'first' : 'last'
    show(key, 'click', true)
  }
  const onTriggerEnter = (key: MenuKey, e: PointerEvent<HTMLButtonElement>) => {
    if (e.pointerType !== 'mouse') return
    clearTimer()
    if (open) {
      if (open !== key) show(key, 'hover')
      return
    }
    timer.current = window.setTimeout(() => show(key, 'hover'), MENU_INTENT_MS)
  }
  const onTriggerLeave = (e: PointerEvent<HTMLButtonElement>) => { if (e.pointerType === 'mouse' && !open) clearTimer() }
  const onNavEnter = (e: PointerEvent<HTMLElement>) => { if (e.pointerType === 'mouse' && open) clearTimer() }
  const onNavLeave = (e: PointerEvent<HTMLElement>) => {
    if (e.pointerType !== 'mouse') return
    clearTimer()
    if (open && via.current === 'hover') timer.current = window.setTimeout(hide, MENU_GRACE_MS)
  }
  const onNavBlur = (e: FocusEvent<HTMLElement>) => { if (open && !navRef.current?.contains(e.relatedTarget as Node | null)) hide() }
  const onPanelKeyDown = (key: MenuKey, e: KeyboardEvent<HTMLDivElement>) => {
    const items = links(panels.current[key])
    const at = items.indexOf(document.activeElement as HTMLElement)
    if (at < 0) return
    let next = -1
    if (e.key === 'ArrowDown' || e.key === 'ArrowRight') next = Math.min(at + 1, items.length - 1)
    else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') next = Math.max(at - 1, 0)
    else if (e.key === 'Home') next = 0
    else if (e.key === 'End') next = items.length - 1
    if (next < 0) return
    e.preventDefault()
    items[next]?.focus()
  }

  const panel = (key: MenuKey, body: ReactNode) => (
    <div
      ref={(el) => { panels.current[key] = el }}
      id={panelId(key)}
      data-open={open === key || undefined}
      inert={open !== key}
      onKeyDown={(e) => onPanelKeyDown(key, e)}
      onClick={(e) => { if ((e.target as Element).closest('a')) hide() }}
      className={cn('ds-menu-panel absolute top-[calc(100%+var(--ds-header-menu-gap))] left-1/2 z-20 rounded-control border border-edge bg-surface-subtle text-fg before:absolute before:inset-x-0 before:bottom-full before:h-(--ds-header-menu-gap)', WIDTH[key])}
    >
      {body}
    </div>
  )
  const has = (key: MenuKey) => entries.some((e) => e.menu === key) && Boolean(menus[key] ?? headerMenus[key])

  return (
    <nav ref={navRef} data-ds="nav-menus" aria-label={label} data-instant={instant || undefined} onPointerEnter={onNavEnter} onPointerLeave={onNavLeave} onBlur={onNavBlur} className={cn('ds-nav-menus relative', from === 1024 ? 'hidden lg:block' : 'hidden xl:block', className)}>
      <style href="ds-nav-menus" precedence="ds">{css}</style>
      <ul className="flex gap-1">
        {entries.map((item) => item.menu ? (
          <li key={item.label} className={item.menu === 'resources' ? 'relative' : undefined}>
            <button
              ref={(el) => { triggers.current[item.menu!] = el }}
              type="button"
              aria-expanded={open === item.menu}
              aria-controls={panelId(item.menu)}
              onClick={(e) => onTriggerClick(item.menu!, e)}
              onKeyDown={(e) => onTriggerKeyDown(item.menu!, e)}
              onPointerEnter={(e) => onTriggerEnter(item.menu!, e)}
              onPointerLeave={onTriggerLeave}
              className={cn(NAV_LINK, 'cursor-pointer gap-1 aria-expanded:bg-surface-raised aria-expanded:text-fg')}
            >
              {item.label}
              <Chevron className="ds-nav-chevron" />
            </button>
            {item.menu === 'resources' && has('resources') ? panel('resources', <ResourcesPanel menu={menus.resources ?? headerMenus.resources} />) : null}
          </li>
        ) : (
          <li key={item.label}><a className={NAV_LINK} href={item.href} aria-current={item.current ? 'page' : undefined}>{item.label}</a></li>
        ))}
      </ul>
      {has('products') ? panel('products', <ProductsLivePanel menu={menus.products ?? headerMenus.products} />) : null}
      {has('useCases') ? panel('useCases', <UseCasesPanel menu={menus.useCases ?? headerMenus.useCases} />) : null}
    </nav>
  )
}

export default NavMenus

const css = `
.ds-menu-panel {
  visibility: hidden; opacity: 0; transform-origin: top center;
  transform: translate(-50%, calc(-1 * var(--ds-header-menu-rise))) scale(var(--ds-menu-from-scale));
  transition: opacity var(--ds-duration-micro) var(--ds-easing-out), transform var(--ds-duration-micro) var(--ds-easing-out), visibility var(--ds-duration-instant) linear var(--ds-duration-micro);
}
.ds-menu-panel[data-open] {
  visibility: visible; opacity: 1; transform: translate(-50%, 0);
  transition: opacity var(--ds-duration-enter) var(--ds-easing-out), transform var(--ds-duration-enter) var(--ds-easing-out), visibility var(--ds-duration-instant);
}
.ds-nav-menus[data-instant] .ds-menu-panel { transition: none; }
.ds-nav-chevron { transition: transform var(--ds-duration-micro) var(--ds-easing-out); }
[aria-expanded="true"] > .ds-nav-chevron { transform: rotate(180deg); }
@media (prefers-reduced-motion: reduce) {
  .ds-menu-panel, .ds-menu-panel[data-open] { transform: translate(-50%, 0); }
  .ds-nav-chevron { transition: none; }
}
`

'use client'
import { useState } from 'react'
import { NavIcon } from '@/react/components/site/NavIcon'
import { BrandLight } from '@/react/components/visuals/BrandLight'
import { headerMenus, type OfferRow, type ResourcesMenu, type SoonRow, type UseCasesMenu } from '@/lib/site-header'
import { cn } from '@/react/lib/cn'
import { imageFit, toSlot } from '@/lib/image'

// The site header's menu panels (site/Header MenuPanels): the use cases (two columns of rows with a 40px glyph, the name
// over a muted line, and a card on the right that crossfades to the row under the pointer or focus: up to three
// pictures and a longer line), the resources (rows with a 32px glyph, a coming-soon row in the faint gray with its
// badge, and the docs card with the brand light drifting behind an install line) and the strip of quieter links at the
// foot. The active row fills #262626 and its glyph brightens; nothing moves but the light (still with reduced motion).
export const ROW = 'group/row flex gap-3 rounded-ds-sm p-3 transition-[background-color] duration-160 ease-out outline-offset-[calc(-1*var(--ds-border-focus))] hover:bg-surface-raised data-active:bg-surface-raised'
