.ds-sheet-collapse > div { min-height: 0; overflow: hidden; }
.ds-sheet-collapse-body { opacity: 0; transition: opacity var(--ds-duration-exit) var(--ds-easing-out); }
.ds-sheet-collapse[data-open="true"] .ds-sheet-collapse-body { opacity: 1; transition-duration: var(--ds-duration-glide); }
.ds-sheet-chevron { transition: transform var(--ds-duration-glide) var(--ds-easing-in-out); }
[aria-expanded="true"] > .ds-sheet-chevron { transform: rotate(180deg); }
@media (prefers-reduced-motion: reduce) {
  .ds-sheet-collapse, .ds-sheet-collapse[data-open="true"], .ds-sheet-chevron { transition: none; }
}
`

import { CHEVRON_PATH, navIconPaths, type NavIconName } from '@/lib/site-header'
import { cn } from '@/react/lib/cn'

// The site's menu glyphs (site/Header NavIcon): two tones on a 24px grid, the body in the gray and the lit part in the
// soft gray, both brightening when the row they sit in is active (--glyph-body, --glyph-lit). And the menus' chevron.
export interface NavIconProps {
  name: NavIconName
  /** 20 or 24px. */
  size?: 20 | 24
  className?: string
}

export function NavIcon({ name, size = 20, className }: NavIconProps) {
  return <svg data-ds="nav-icon" viewBox="0 0 24 24" width={size} height={size} aria-hidden="true" focusable="false" className={cn('block flex-none', className)} dangerouslySetInnerHTML={{ __html: navIconPaths(name) }} />
}

export function Chevron({ size = 12, className }: { size?: 12 | 16; className?: string }) {
  return <svg viewBox="0 0 12 12" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false" className={cn('flex-none', className)} dangerouslySetInnerHTML={{ __html: CHEVRON_PATH }} />
}

export default NavIcon

import type { ProductVisualKind } from '@/lib/product-visual-data'
import type { ImageSlot } from '@/lib/image'
// The site header's content and glyphs (site/Header, content/nav.ts, content/home.ts): the nav, the three menus and the
// menu icons, the same in both flavors. Copy is Acme's; platforms are named in words (never their logos); pictures come
// in through `picture` and `shots` (none by default, so no one's photo is shown unless you pass it).

export type NavIconName =
	| 'brand' | 'creator' | 'media' | 'insights' | 'landing' | 'collabs' | 'comments' | 'tagged' | 'soon' | 'paid' | 'organic'
	| 'creators' | 'monitor' | 'trend' | 'build' | 'research' | 'templates' | 'docs' | 'blog' | 'articles' | 'demos' | 'careers'

export type MenuKey = 'products' | 'useCases' | 'resources'

export interface NavEntry {
	label: string
	/** A plain link. */
	href?: string
	/** Opens this menu instead (from 1280; a disclosure in the phone sheet, resources a link to `resources.all`). */
	menu?: MenuKey
	/** The page being shown. */
	current?: boolean
}

export interface MenuLink { label: string; href: string }

export interface OfferRow {
	key: string
	name: string
	line: string
	href: string
	icon: NavIconName
	/** Where it is live, in words: a chip on the live card. */
	platforms?: string[]
	/** The product's looping scene on the live card (a `product-visual` kind), as on the site. */
	visual?: ProductVisualKind
	/** A picture for the live card (a src or { src, alt, fit, position }; a product shot, never a person's photo by
	 * default); it takes the place of `visual`. Without either the card shows the product's glyph, marked as a placeholder. */
	picture?: string | ImageSlot
}

export interface SoonRow {
	key: string
	name: string
	line: string
	href: string
	icon: NavIconName
	/** The live card's groups: a label over the platforms or integrations, in words. */
	groups: { label: string; items: string[] }[]
}

export interface ProductsMenu { offers: OfferRow[]; soon?: SoonRow; strip: { label: string; links: MenuLink[] } }

export interface CaseRow {
	key: string
	name: string
	line: string
	href: string
	icon: NavIconName
	/** The card's longer line. */
	card?: string
	/** Up to three pictures for the card (4:5), each a src or { src, alt, fit, position }; empty tiles when left out. */
	shots?: (string | ImageSlot)[]
}

export interface UseCasesMenu { rows: CaseRow[]; all: MenuLink; more: MenuLink[] }

export interface ResourceRow { key: string; title: string; href: string; icon: NavIconName; soon?: boolean; external?: boolean }

export interface ResourcesMenu {
	rows: ResourceRow[]
	all: MenuLink
	feature: { title: string; line: string; href: string; code: string; external?: boolean }
	soonLabel: string
}

export interface HeaderMenus { products?: ProductsMenu; useCases?: UseCasesMenu; resources?: ResourcesMenu }

export interface HeaderLabels { nav: string; menu: string; close: string; home: string }

export const headerNav: NavEntry[] = [
	{ label: 'Products', menu: 'products' },
